class error_code {
    int val_;
    const error_category* cat_; // Pointer overhead (8 bytes typical)

public:
    error_code(int v, const error_category& c) noexcept
        : val_(v), cat_(&c) {}

    const error_category& category() const noexcept { return *cat_; }
    int value() const noexcept { return val_; }

    // Fast check: category pointer equality + value comparison
    bool operator==(const error_code& other) const noexcept {
        return val_ == other.val_ && cat_ == other.cat_;
    }
    // Hashing combines val_ and cat_ address for lookup efficiency.
};

// ---

class error_category {
public:
    // Virtual call overhead for cross-category comparison
    virtual bool equivalent(int code,
                            const error_condition& condition) const noexcept = 0;

    // Default implementations rely on system/generic singletons
    static const error_category& generic_category() noexcept;

    // OS/C errno mapping uses category-specific equivalent logic
    error_condition make_error_condition(int ev) const {
        return error_condition(ev, *this);
    }
};
